// CORE-6102: "Use AI" on fields and table columns has three stored states,
// and the masks used to show them as a two-state checkbox. The backend
// annotates every field/column with what structured extraction really does
// (helpers/ai_field_selection.py in doc2-api); this file turns that into the
// dropdown value and writes the chosen value back into additional_attributes.

export type UseAiChoice = 'default' | 'yes' | 'no';
export type UseAiSource = 'explicit_on' | 'explicit_off' | 'default_on' | 'default_off';

type Attrs = Record<string, unknown>;

export function parseAttributes(raw: unknown): Attrs {
  if (!raw) return {};
  if (typeof raw === 'object') return { ...(raw as Attrs) };
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === 'object' ? parsed : {};
    } catch {
      return {};
    }
  }
  return {};
}

/** The dropdown value for a row. Prefers the backend's use_ai_source. */
export function choiceOf(row: { use_ai_source?: string; additional_attributes?: unknown }): UseAiChoice {
  switch (row.use_ai_source) {
    case 'explicit_on':
      return 'yes';
    case 'explicit_off':
      return 'no';
    case 'default_on':
    case 'default_off':
      return 'default';
  }
  const attrs = parseAttributes(row.additional_attributes);
  if (!('use_ai' in attrs)) return 'default';
  return attrs.use_ai === true ? 'yes' : attrs.use_ai === false ? 'no' : 'default';
}

/** additional_attributes after choosing: "default" removes the key. */
export function applyChoice(raw: unknown, choice: UseAiChoice): Attrs {
  const attrs = parseAttributes(raw);
  if (choice === 'default') delete attrs.use_ai;
  else attrs.use_ai = choice === 'yes';
  return attrs;
}

/** What the row means after the choice, for the local copy of the row. */
export function stateAfter(choice: UseAiChoice, isDefault: boolean): { use_ai_source: UseAiSource; use_ai_effective: boolean } {
  if (choice === 'yes') return { use_ai_source: 'explicit_on', use_ai_effective: true };
  if (choice === 'no') return { use_ai_source: 'explicit_off', use_ai_effective: false };
  return isDefault
    ? { use_ai_source: 'default_on', use_ai_effective: true }
    : { use_ai_source: 'default_off', use_ai_effective: false };
}

/** True when a default field/column is switched off (highlighted in the mask). */
export function isDefaultSwitchedOff(row: { use_ai_source?: string; use_ai_is_default?: boolean }): boolean {
  return row.use_ai_source === 'explicit_off' && row.use_ai_is_default === true;
}

export interface UseAiOption {
  value: UseAiChoice;
  label: string;
}

/** Dropdown options; each label says whether the AI requests the field. */
export function optionsFor(isDefault: boolean, t: (key: string) => string): UseAiOption[] {
  return [
    { value: 'default', label: t(isDefault ? 'use_ai_option_default_on' : 'use_ai_option_default_off') },
    { value: 'yes', label: t('use_ai_option_yes') },
    { value: 'no', label: t('use_ai_option_no') },
  ];
}
